import csv, json
from pathlib import Path

JSON_IN = Path('/root/trivy_report.json')
CSV_OUT = Path('/root/security_audit.csv')

SEV_KEEP = {'HIGH', 'CRITICAL'}


def cvss_score(vuln: dict):
    cvss = vuln.get('CVSS') or {}
    if isinstance(cvss, dict):
        # Prefer v3 score from authoritative sources
        for src in ('nvd', 'ghsa', 'redhat'):
            ent = cvss.get(src)
            if isinstance(ent, dict):
                v3 = ent.get('V3Score')
                if isinstance(v3, (int, float)):
                    return v3
        # Fallback to v2 (rarely needed)
        for src in ('nvd', 'ghsa', 'redhat'):
            ent = cvss.get(src)
            if isinstance(ent, dict):
                v2 = ent.get('V2Score')
                if isinstance(v2, (int, float)):
                    return v2
    return 'N/A'


def best_of(a: dict, b: dict) -> dict:
    def score(v: dict) -> int:
        s = 0
        url = v.get('PrimaryURL') or ''
        if isinstance(url, str) and url.strip():
            s += 4
        if cvss_score(v) != 'N/A':
            s += 2
        fixed = v.get('FixedVersion') or ''
        if isinstance(fixed, str) and fixed.strip():
            s += 1
        title = v.get('Title') or v.get('Description') or ''
        if isinstance(title, str) and title.strip():
            s += 1
        return s

    return a if score(a) >= score(b) else b


with JSON_IN.open('r', encoding='utf-8') as f:
    data = json.load(f)

best_by_key = {}

for result in (data.get('Results') or []):
    for vuln in (result.get('Vulnerabilities') or []):
        sev = vuln.get('Severity') or 'UNKNOWN'
        if sev not in SEV_KEEP:
            continue

        pkg = vuln.get('PkgName') or 'Unknown'
        ver = vuln.get('InstalledVersion') or 'N/A'
        vid = vuln.get('VulnerabilityID') or 'N/A'
        key = (pkg, ver, vid)

        if key in best_by_key:
            best_by_key[key] = best_of(best_by_key[key], vuln)
        else:
            best_by_key[key] = vuln

rows = []
for (pkg, ver, vid), vuln in best_by_key.items():
    fixed = vuln.get('FixedVersion')
    if not (isinstance(fixed, str) and fixed.strip()):
        fixed = 'N/A'

    title = vuln.get('Title')
    if not (isinstance(title, str) and title.strip()):
        title = vuln.get('Description')
    if not (isinstance(title, str) and title.strip()):
        title = 'N/A'

    url = vuln.get('PrimaryURL')
    if not (isinstance(url, str) and url.strip()):
        refs = vuln.get('References')
        if isinstance(refs, list) and refs:
            url = refs[0]
        else:
            url = ''

    rows.append({
        'Package': pkg,
        'Version': ver,
        'CVE_ID': vid,
        'Severity': vuln.get('Severity') or 'UNKNOWN',
        'CVSS_Score': cvss_score(vuln),
        'Fixed_Version': fixed,
        'Title': title,
        'Url': url,
    })

rows.sort(key=lambda r: (r['Package'], r['Version'], r['CVE_ID']))

headers = ['Package','Version','CVE_ID','Severity','CVSS_Score','Fixed_Version','Title','Url']
with CSV_OUT.open('w', newline='', encoding='utf-8') as f:
    w = csv.DictWriter(f, fieldnames=headers)
    w.writeheader()
    w.writerows(rows)

print(f'Wrote {len(rows)} HIGH/CRITICAL vulnerabilities to {CSV_OUT}')
PY

